# ============================================================
# Script: 07_macrophage_subcluster_analysis.R
# Project: Adipose scRNA-seq analysis
# Purpose: Subcluster macrophages and perform subcluster-level DE analysis
# Author: Yi Hu
# ============================================================

# This script provides the core macrophage subcluster analysis workflow.
# It starts from the annotated integrated Seurat object generated by
# 03_clustering_annotation.R.
#
# Input:
#   results/annotation/seurat_integrated_annotated.rds
#
# Output:
#   results/macrophage_subcluster/seurat_macrophage_subcluster_annotated.rds
#   results/macrophage_subcluster/macrophage_subcluster_markers_all.csv
#   results/macrophage_subcluster/macrophage_subcluster_markers_top20.csv
#   results/macrophage_subcluster/macrophage_subcluster_counts_by_condition.csv
#   results/macrophage_subcluster/macrophage_subcluster_fraction_by_condition.csv
#   results/macrophage_subcluster/macrophage_subcluster_DE_combined.csv
#   results/macrophage_subcluster/IPA_input/

# -----------------------------
# 1. Load packages
# -----------------------------

suppressPackageStartupMessages({
  library(Seurat)
  library(tidyverse)
  library(tibble)
  library(forcats)
})

# -----------------------------
# 2. Define input and output paths
# -----------------------------

input_file <- "results/annotation/seurat_integrated_annotated.rds"
output_dir <- "results/macrophage_subcluster"

dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)

# -----------------------------
# 3. Load annotated Seurat object
# -----------------------------

seurat_obj <- readRDS(input_file)

# The major cell type annotation should have been added in:
# scripts/03_clustering_annotation.R

Idents(seurat_obj) <- "cell_type"

# -----------------------------
# 4. Subset macrophages
# -----------------------------

macro_obj <- subset(
  x = seurat_obj,
  idents = "Macrophage"
)

macro_cell_counts <- macro_obj@meta.data %>%
  count(condition, name = "n_cells")

write.csv(
  macro_cell_counts,
  file = file.path(output_dir, "macrophage_cell_counts_by_condition.csv"),
  row.names = FALSE
)

# -----------------------------
# 5. Re-integrate / re-cluster macrophages
# -----------------------------

# Macrophages were reprocessed independently to resolve macrophage
# subclusters. Samples are split by condition and integrated using
# SCT integration.

macro_list <- SplitObject(
  object = macro_obj,
  split.by = "condition"
)

macro_list <- lapply(
  X = macro_list,
  FUN = function(obj) {
    SCTransform(
      object = obj,
      assay = "RNA",
      verbose = FALSE
    )
  }
)

macro_features <- SelectIntegrationFeatures(
  object.list = macro_list,
  nfeatures = 3000
)

macro_list <- PrepSCTIntegration(
  object.list = macro_list,
  anchor.features = macro_features
)

macro_anchors <- FindIntegrationAnchors(
  object.list = macro_list,
  normalization.method = "SCT",
  anchor.features = macro_features
)

macro_integrated <- IntegrateData(
  anchorset = macro_anchors,
  normalization.method = "SCT"
)

DefaultAssay(macro_integrated) <- "integrated"

# -----------------------------
# 6. Dimensionality reduction
# -----------------------------

macro_integrated <- RunPCA(
  object = macro_integrated,
  verbose = FALSE
)

pdf(file.path(output_dir, "macrophage_elbow_plot.pdf"), width = 5, height = 4)
ElbowPlot(macro_integrated, ndim = 30)
dev.off()

n_pcs <- 20

macro_integrated <- RunUMAP(
  object = macro_integrated,
  reduction = "pca",
  dims = 1:n_pcs
)

# -----------------------------
# 7. Graph-based clustering
# -----------------------------

macro_integrated <- FindNeighbors(
  object = macro_integrated,
  reduction = "pca",
  dims = 1:n_pcs,
  verbose = FALSE
)

# The final macrophage subcluster annotation was based on resolution 0.3.

selected_resolution <- 0.3

macro_integrated <- FindClusters(
  object = macro_integrated,
  resolution = selected_resolution,
  verbose = FALSE
)

macro_integrated$macrophage_cluster <- Idents(macro_integrated)

# Minimal QC UMAPs.

p_macro_cluster <- DimPlot(
  object = macro_integrated,
  reduction = "umap",
  label = TRUE
) +
  ggtitle("Macrophage subclusters")

ggsave(
  filename = file.path(output_dir, "macrophage_umap_by_cluster.pdf"),
  plot = p_macro_cluster,
  width = 6,
  height = 5
)

p_macro_condition <- DimPlot(
  object = macro_integrated,
  reduction = "umap",
  group.by = "condition"
) +
  ggtitle("Macrophages by condition")

ggsave(
  filename = file.path(output_dir, "macrophage_umap_by_condition.pdf"),
  plot = p_macro_condition,
  width = 6,
  height = 5
)

# -----------------------------
# 8. Identify macrophage subcluster markers
# -----------------------------

DefaultAssay(macro_integrated) <- "SCT"

macro_integrated <- PrepSCTFindMarkers(macro_integrated)

Idents(macro_integrated) <- "seurat_clusters"

macrophage_subcluster_markers <- FindAllMarkers(
  object = macro_integrated,
  only.pos = TRUE,
  min.pct = 0.25,
  logfc.threshold = 0.25,
  test.use = "wilcox"
)

write.csv(
  macrophage_subcluster_markers,
  file = file.path(output_dir, "macrophage_subcluster_markers_all.csv"),
  row.names = FALSE
)

macrophage_subcluster_markers_top20 <- macrophage_subcluster_markers %>%
  group_by(cluster) %>%
  slice_max(order_by = avg_log2FC, n = 20, with_ties = FALSE)

write.csv(
  macrophage_subcluster_markers_top20,
  file = file.path(output_dir, "macrophage_subcluster_markers_top20.csv"),
  row.names = FALSE
)

# -----------------------------
# 9. Review canonical macrophage subcluster markers
# -----------------------------

# Marker genes used to support macrophage subcluster annotation.
# This concise marker list records the biological basis of annotation,
# while publication-quality figure styling was performed separately.

macrophage_marker_genes <- c(
  # Pan-macrophage / myeloid markers
  "Ptprc", "Lyz2", "Adgre1", "Csf1r", "Mertk", "Cd68",
  
  # NPVM / antigen-presenting macrophage-like markers
  "Cd74", "H2-Aa", "H2-Ab1", "Apoe", "Fcrls", "Fcgr3",
  
  # PVM markers
  "Lyve1", "Cd163", "Mrc1", "Mctp2", "Dnm1",
  
  # LAM markers
  "Lpl", "Trem2", "Cd9", "Rnf128",
  
  # AM-like markers
  "Gpr141", "Plac8", "Itgal",
  
  # Collagen-expressing macrophage markers
  "Col1a1", "Col3a1", "Col5a2", "Lama2", "Lama5", "Tgfbr3",
  
  # Proliferating macrophage markers
  "Pola1", "Kif11", "Kif15", "Kif2c", "Cdca2",
  
  # Resident macrophage-like markers
  "Prg4", "Tgfb2", "Ltbp1", "Cxcl13"
)

macrophage_marker_genes <- macrophage_marker_genes[
  macrophage_marker_genes %in% rownames(macro_integrated)
]

p_macro_marker_dotplot <- DotPlot(
  object = macro_integrated,
  features = macrophage_marker_genes
) +
  RotatedAxis() +
  ggtitle("Canonical markers for macrophage subcluster annotation")

ggsave(
  filename = file.path(output_dir, "macrophage_subcluster_marker_dotplot.pdf"),
  plot = p_macro_marker_dotplot,
  width = 13,
  height = 5
)

# -----------------------------
# 10. Annotate macrophage subclusters
# -----------------------------

# The cluster-to-subcluster mapping below follows the final macrophage
# annotation used in the analysis.
#
# NPVM: non-perivascular macrophages
# PVM: perivascular macrophages
# LAM: lipid-associated macrophages
# PLAM: proliferating lipid-associated macrophages
# CEM1/CEM2: collagen-expressing macrophage subsets
# AM: activated macrophage-like subset
# RM: resident macrophage-like subset

macrophage_subcluster_annotation <- tibble::tribble(
  ~cluster, ~macrophage_subcluster,
  "0",      "NPVM",
  "6",      "NPVM",
  "3",      "PVM",
  "4",      "PVM",
  "1",      "LAM",
  "8",      "PLAM",
  "5",      "CEM1",
  "10",     "CEM1",
  "7",      "CEM2",
  "2",      "AM",
  "9",      "RM"
)

write.csv(
  macrophage_subcluster_annotation,
  file = file.path(output_dir, "macrophage_cluster_to_subcluster_annotation.csv"),
  row.names = FALSE
)

metadata <- macro_integrated@meta.data %>%
  as.data.frame() %>%
  tibble::rownames_to_column("barcode") %>%
  mutate(seurat_clusters = as.character(seurat_clusters)) %>%
  left_join(
    macrophage_subcluster_annotation,
    by = c("seurat_clusters" = "cluster")
  ) %>%
  tibble::column_to_rownames("barcode")

metadata$macrophage_subcluster <- forcats::fct_explicit_na(
  metadata$macrophage_subcluster,
  na_level = "Unknown"
)

macro_integrated$macrophage_subcluster <- metadata[
  rownames(macro_integrated@meta.data),
  "macrophage_subcluster"
]

macro_integrated$macrophage_subcluster <- factor(
  macro_integrated$macrophage_subcluster,
  levels = c(
    "NPVM",
    "PVM",
    "LAM",
    "AM",
    "CEM1",
    "CEM2",
    "PLAM",
    "RM",
    "Unknown"
  )
)

# -----------------------------
# 11. Remove unassigned / unknown clusters if present
# -----------------------------

# If all clusters were assigned, this step will not remove anything.
# It is included for consistency with the ASPC and EC subcluster scripts.

Idents(macro_integrated) <- "macrophage_subcluster"

if ("Unknown" %in% levels(Idents(macro_integrated))) {
  macro_integrated <- subset(
    x = macro_integrated,
    idents = "Unknown",
    invert = TRUE
  )
}

macro_integrated$macrophage_subcluster <- droplevels(
  macro_integrated$macrophage_subcluster
)

# -----------------------------
# 12. Create subcluster-condition groups
# -----------------------------

# Example values:
# LAM-Chow, LAM-HFSC, PVM-Chow, PVM-HFSC

macro_integrated$DE_subgroup <- paste0(
  macro_integrated$macrophage_subcluster,
  "-",
  macro_integrated$condition
)

macro_integrated$DE_subgroup <- factor(macro_integrated$DE_subgroup)

# -----------------------------
# 13. Summarize macrophage subcluster composition
# -----------------------------

macrophage_subcluster_counts <- macro_integrated@meta.data %>%
  count(condition, macrophage_subcluster, name = "n_cells")

write.csv(
  macrophage_subcluster_counts,
  file = file.path(output_dir, "macrophage_subcluster_counts_by_condition.csv"),
  row.names = FALSE
)

macrophage_subcluster_fraction <- macrophage_subcluster_counts %>%
  group_by(condition) %>%
  mutate(fraction = n_cells / sum(n_cells)) %>%
  ungroup()

write.csv(
  macrophage_subcluster_fraction,
  file = file.path(output_dir, "macrophage_subcluster_fraction_by_condition.csv"),
  row.names = FALSE
)

# Minimal annotated UMAP.

p_macro_annotated <- DimPlot(
  object = macro_integrated,
  reduction = "umap",
  group.by = "macrophage_subcluster",
  label = TRUE
) +
  ggtitle("Annotated macrophage subclusters")

ggsave(
  filename = file.path(output_dir, "macrophage_umap_annotated_subclusters.pdf"),
  plot = p_macro_annotated,
  width = 6,
  height = 5
)

# -----------------------------
# 14. Differential expression within macrophage subclusters
# -----------------------------

DefaultAssay(macro_integrated) <- "RNA"

# For Seurat v5 objects, join RNA layers before differential expression.
macro_integrated <- JoinLayers(macro_integrated)

macro_integrated <- NormalizeData(
  object = macro_integrated,
  assay = "RNA",
  verbose = FALSE
)

Idents(macro_integrated) <- "DE_subgroup"

condition_1 <- "HFSC"
condition_2 <- "Chow"

macrophage_subclusters <- c(
  "NPVM",
  "PVM",
  "LAM",
  "AM",
  "CEM1",
  "CEM2",
  "PLAM",
  "RM"
)

macrophage_de_results_list <- list()

for (subcluster in macrophage_subclusters) {
  
  message("Running DE analysis for macrophage subcluster: ", subcluster)
  
  ident_1 <- paste(subcluster, condition_1, sep = "-")
  ident_2 <- paste(subcluster, condition_2, sep = "-")
  
  if (!(ident_1 %in% levels(Idents(macro_integrated))) ||
      !(ident_2 %in% levels(Idents(macro_integrated)))) {
    
    warning("Skipping ", subcluster, ": one or both comparison groups are missing.")
    next
  }
  
  markers <- FindMarkers(
    object = macro_integrated,
    ident.1 = ident_1,
    ident.2 = ident_2,
    logfc.threshold = 0,
    min.pct = 0.1,
    test.use = "wilcox"
  )
  
  markers_df <- markers %>%
    as.data.frame() %>%
    rownames_to_column(var = "gene") %>%
    arrange(p_val_adj) %>%
    mutate(
      cell_type = "Macrophage",
      subcluster = subcluster,
      comparison = paste(condition_1, "vs", condition_2)
    )
  
  write.csv(
    markers_df,
    file = file.path(
      output_dir,
      paste0("Macrophage_", subcluster, "_", condition_1, "_vs_", condition_2, "_DE.csv")
    ),
    row.names = FALSE
  )
  
  macrophage_de_results_list[[subcluster]] <- markers_df
}

# -----------------------------
# 15. Combine macrophage subcluster DE results
# -----------------------------

macrophage_de_combined <- bind_rows(macrophage_de_results_list)

write.csv(
  macrophage_de_combined,
  file = file.path(output_dir, "macrophage_subcluster_DE_combined.csv"),
  row.names = FALSE
)

# -----------------------------
# 16. Generate filtered DEG table
# -----------------------------

# This table can be used for pathway analysis input.
# Thresholds should match the manuscript Methods section.

macrophage_de_filtered <- macrophage_de_combined %>%
  filter(
    p_val_adj < 0.05,
    abs(avg_log2FC) >= 0.25
  )

write.csv(
  macrophage_de_filtered,
  file = file.path(output_dir, "macrophage_subcluster_DE_filtered_FDR005_logFC025.csv"),
  row.names = FALSE
)

# -----------------------------
# 17. Export IPA input tables
# -----------------------------

ipa_output_dir <- file.path(output_dir, "IPA_input")
dir.create(ipa_output_dir, recursive = TRUE, showWarnings = FALSE)

for (subcluster in unique(macrophage_de_filtered$subcluster)) {
  
  ipa_table <- macrophage_de_filtered %>%
    filter(subcluster == !!subcluster) %>%
    select(gene, avg_log2FC, p_val, p_val_adj)
  
  write.csv(
    ipa_table,
    file = file.path(
      ipa_output_dir,
      paste0("Macrophage_", subcluster, "_IPA_input.csv")
    ),
    row.names = FALSE
  )
}

# -----------------------------
# 18. Save macrophage subcluster object
# -----------------------------

saveRDS(
  macro_integrated,
  file = file.path(output_dir, "seurat_macrophage_subcluster_annotated.rds")
)

# -----------------------------
# 19. Session information
# -----------------------------

sink(file.path(output_dir, "session_info_macrophage_subcluster.txt"))
sessionInfo()
sink()